def find_duplicates(input_list):
    """
    Returns a list of integers that appear more than once in the input list
    while maintaining the original order of their first occurrence.
    """
    if not all(isinstance(x, int) for x in input_list):
        raise ValueError("All elements of the input list must be integers")

    seen = set()
    duplicates = set()
    result = []

    for num in input_list:
        if num in seen:
            if num not in duplicates:
                result.append(num)
                duplicates.add(num)
        else:
            seen.add(num)

    return result

