def spiral_order(matrix):
    """
    Returns the elements of the 2D matrix in clockwise spiral order.
    """
    if not matrix:
        return []

    result = []
    while matrix:
        # add the first row from the remaining rows
        result += matrix.pop(0)
        # add the last element from the remaining rows
        if matrix and matrix[0]:
            for row in matrix:
                result.append(row.pop())
        # add the last row from the remaining rows
        if matrix:
            result += matrix.pop()[::-1]
        # add the first element from the remaining rows
        if matrix and matrix[0]:
            for row in matrix[::-1]:
                result.append(row.pop(0))
    return result

