from typing import List

def find_duplicates(input_list: List[int]) -> List[int]:
    """
    Identifies all the duplicate elements in a list of integers and returns them in a sorted list.

    Parameters:
    input_list (List[int]): A list of integers which may contain duplicates.

    Returns:
    List[int]: A sorted list of integers which are duplicates in input_list. Each duplicate appears only once.
    """
    element_count = {}
    for element in input_list:
        if element in element_count:
            element_count[element] += 1
        else:
            element_count[element] = 1

    duplicates = [element for element, count in element_count.items() if count > 1]

    return sorted(duplicates)

