import string
from collections import Counter

def get_most_frequent_words(file_path: str, top_n: int) -> list | None:
    if not file_path or not isinstance(file_path, str) or not isinstance(top_n, int) or top_n <= 0:
        return None
    try:
        with open(file_path, 'r') as file:
            text = file.read().lower()
            text = text.translate(str.maketrans('', '', string.punctuation))
            words = text.split()
            word_counts = Counter(words)
            most_common_words = word_counts.most_common(top_n)

            result = [
                {'word': word, 'count': count}
                for word, count in most_common_words
            ]
            return result
    except Exception:
        return None

def select_event_loop(platform_name: str, version: float) -> str:
    """
    Determines the appropriate asyncio event loop for the given platform and version constraints.

    Parameters:
    - platform_name (str): The platform name ('Windows', 'macOS', etc.)
    - version (float): The version number of the operating system

    Returns:
    - str: The name of the most compatible asyncio event loop.
    """
    if platform_name == 'Windows':
        return 'ProactorEventLoop'  # Assuming ProactorEventLoop is supported on all Windows versions
    elif platform_name == 'macOS':
        if version <= 10.8:
            return 'SelectSelector'
        else:
            return 'KqueueSelector'
    else:
        return 'UnknownEventLoop'

