from typing import List, Dict
import pandas as pd

def identify_fraudulent_activity(transactions: List[Dict], threshold: int, time_period: str) -> List[str]:
    # Parse the transactions into a DataFrame
    df = pd.DataFrame(transactions)
    df['timestamp'] = pd.to_datetime(df['timestamp'])

    # Extract the numeric value and unit from the time_period
    value, unit = time_period.split()
    value = int(value)

    # Define the frequency string for pandas offset
    if unit.startswith('minute'):
        time_range = f'{value}T'
    elif unit.startswith('hour'):
        time_range = f'{value}H'
    elif unit.startswith('day'):
        time_range = f'{value}D'
    else:
        raise ValueError("Unsupported time unit. Use 'minutes', 'hours', or 'days'.")

    # Create an empty list to store fraudulent customer IDs
    fraudulent_customers = set()

    # Group by each customer and check their transaction count within the time period
    for customer_id, group in df.groupby('customer_id'):
        time_windows = group['timestamp'].apply(lambda x: pd.date_range(start=x, periods=2, freq=time_range)[1])
        for window_start, window_end in zip(group['timestamp'], time_windows):
            count_in_range = group[(group['timestamp'] >= window_start) & (group['timestamp'] < window_end)].shape[0]
            if count_in_range > threshold:
                fraudulent_customers.add(customer_id)
                break

    return list(fraudulent_customers)

def binary_search_insert_position(nums, target):
    """
    Searches for the target in the sorted list nums.
    Returns the index of the target if found.
    If the target is not found, returns the index where it should be inserted to maintain the sorted order.
    """
    left, right = 0, len(nums) - 1

    while left <= right:
        mid = (left + right) // 2
        if nums[mid] == target:
            return mid
        elif nums[mid] < target:
            left = mid + 1
        else:
            right = mid - 1

    return left

