def find_longest_alphabetical_subarray(seq):
    """
    Finds the longest subarray which has all the characters in alphabetical order in a given list of lowercase alphabets.

    Args:
    seq (list): A list of lowercase alphabetical characters.

    Returns:
    tuple: A tuple containing the starting and ending indices of the longest alphabetical subarray.
    """
    if not seq:
        return (0, 0)

    max_len = 1
    current_len = 1
    start_index = 0
    max_start_index = 0

    for i in range(1, len(seq)):
        if seq[i] >= seq[i - 1]:
            current_len += 1
        else:
            if current_len > max_len:
                max_len = current_len
                max_start_index = start_index
            current_len = 1
            start_index = i

    # Final check for the last subarray
    if current_len > max_len:
        max_len = current_len
        max_start_index = start_index

    return (max_start_index, max_start_index + max_len - 1)

