def min_edit_distance(word1: str, word2: str) -> int:
    # Length of the two words
    m, n = len(word1), len(word2)

    # Initialize the DP table with dimensions (m+1) x (n+1)
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Base cases: transforming from empty string to word2 and vice versa
    for i in range(1, m+1):
        dp[i][0] = i
    for j in range(1, n+1):
        dp[0][j] = j

    # Fill the DP table
    for i in range(1, m+1):
        for j in range(1, n+1):
            if word1[i-1] == word2[j-1]:
                dp[i][j] = dp[i-1][j-1]  # No operation needed
            else:
                # Minimum of deleting from word1, inserting into word1, or replacing character
                dp[i][j] = min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1]) + 1

    return dp[m][n]

