def max_sum_submatrix(matrix, k):
    n = len(matrix)

    # If the size of the matrix is smaller than k, return -1
    if k > n:
        return -1

    # Initialize the maximum sum to a very small number
    max_sum = float('-inf')

    # Calculate the sums of all k x k submatrices
    for i in range(n - k + 1):
        for j in range(n - k + 1):
            current_sum = 0
            for x in range(i, i + k):
                for y in range(j, j + k):
                    current_sum += matrix[x][y]
            max_sum = max(max_sum, current_sum)

    return max_sum

