reference_solution:
def validate_payload(payload):
    """
    Validates the given JSON payload against the specified conditions.

    Args:
    payload (dict): The JSON payload to be validated.

    Returns:
    bool: True if the payload fulfills all the conditions, False otherwise.
    """
    if not isinstance(payload, dict):
        return False

    # Required properties
    required_props = ["name", "age", "city", "interests", "isEmployed", "workExperience"]

    # Check for required properties, specific types and additional "workExperience" object check
    for prop in required_props:
        if prop not in payload:
            return False

    if not isinstance(payload["name"], str):
        return False
    if not isinstance(payload["age"], int):
        return False
    if not isinstance(payload["city"], str):
        return False
    if not isinstance(payload["interests"], list) or not all(isinstance(i, str) for i in payload["interests"]):
        return False
    if not isinstance(payload["isEmployed"], bool):
        return False
    if not isinstance(payload["workExperience"], dict):
        return False

    work_exp = payload["workExperience"]
    if "company" not in work_exp or not isinstance(work_exp["company"], str):
        return False
    if "duration" not in work_exp or not isinstance(work_exp["duration"], int):
        return False

    return True

