def fizzbuzz(n):
    """
    Returns a list of strings from 1 to n following the FizzBuzz rules:
    - For multiples of 3, return "Fizz" instead of the number.
    - For multiples of 5, return "Buzz" instead of the number.
    - For multiples of 15, return "FizzBuzz" instead of the number.
    """
    result = []
    for i in range(1, n + 1):
        if i % 15 == 0:
            result.append("FizzBuzz")
        elif i % 3 == 0:
            result.append("Fizz")
        elif i % 5 == 0:
            result.append("Buzz")
        else:
            result.append(str(i))
    return result

