from typing import List

def longest_common_prefix(strs: List[str]) -> str:
    if not strs:
        return ""

    min_length = min(len(s) for s in strs)
    lcp = []

    for i in range(min_length):
        current_char = strs[0][i]
        for s in strs:
            if s[i] != current_char:
                return ''.join(lcp)
        lcp.append(current_char)

    return ''.join(lcp)

