def max_profit(prices):
    """
    Computes the maximum profit that can be made from buying and selling stocks on different days.

    :param prices: List[int], a list of integers representing the stock prices on consecutive days
    :return: int, the maximum profit that can be achieved, or 0 if no profit can be made
    """
    if not prices or len(prices) < 2:
        return 0

    min_price = float('inf')
    max_prof = 0

    for price in prices:
        if price < min_price:
            min_price = price
        elif price - min_price > max_prof:
            max_prof = price - min_price

    return max_prof

