def find_potential_duplicates(users):
    name_dict = {}
    email_dict = {}
    duplicates = set()

    for user in users:
        user_id = user['id']
        name = user['name']
        email = user['email']

        if name in name_dict:
            for duplicate_id in name_dict[name]:
                duplicates.add((min(user_id, duplicate_id), max(user_id, duplicate_id)))
            name_dict[name].append(user_id)
        else:
            name_dict[name] = [user_id]

        if email in email_dict:
            for duplicate_id in email_dict[email]:
                duplicates.add((min(user_id, duplicate_id), max(user_id, duplicate_id)))
            email_dict[email].append(user_id)
        else:
            email_dict[email] = [user_id]

    return sorted(list(duplicates))

