def remove_duplicates(s):
    """
    Removes all duplicate characters from a string while 
    maintaining the original order of the characters.
    """
    seen = set()
    result = []
    for char in s:
        if char not in seen:
            seen.add(char)
            result.append(char)
    return ''.join(result)

