def count_letters(input_string):
    """
    Takes a string as an input and returns a dictionary where the keys are 
    lowercase letters and the values are the counts of those letters in the string.
    Non-letter characters are ignored.
    """
    letter_count = {}

    for char in input_string:
        if char.isalpha():
            char_lower = char.lower()
            if char_lower in letter_count:
                letter_count[char_lower] += 1
            else:
                letter_count[char_lower] = 1

    return letter_count

