def longest_subarray_length(arr):
    """
    Returns the length of the longest contiguous subarray where all elements have the same value.

    :param arr: List[int] - list of integers
    :return: int - length of the longest contiguous subarray with the same value
    """
    if not arr:
        return 0

    max_len = current_len = 1
    for i in range(1, len(arr)):
        if arr[i] == arr[i - 1]:
            current_len += 1
        else:
            if current_len > max_len:
                max_len = current_len
            current_len = 1
    # Check for the last subarray
    if current_len > max_len:
        max_len = current_len

    return max_len

