def find_book_location(library, book_id):
    """
    This function finds the book's location in the library.

    Parameters:
    library (list): A 3D list where library[f][s] is the list of book IDs on the s-th bookshelf on the f-th floor.
    book_id (int): The ID of the book.

    Returns:
    tuple: A tuple (floor, shelf) where the book is found, otherwise (-1, -1).
    """
    for f in range(len(library)):
        for s in range(len(library[f])):
            if book_id in library[f][s]:
                return (f, s)
    return (-1, -1)

