import contextvars

def record_user_action(initial_context, actions):
    context_vars = {}
    tokens = {}

    # Initialize context variables with the initial context.
    for key, value in initial_context.items():
        context_vars[key] = contextvars.ContextVar(key, default=value)

    # Perform actions.
    for action_name, context_var_name, value in actions:
        if action_name == 'set':
            tokens[context_var_name] = context_vars[context_var_name].set(value)
        elif action_name == 'reset':
            context_vars[context_var_name].reset(tokens[context_var_name])

    # Generate the final context state.
    final_state = {key: var.get() for key, var in context_vars.items()}

    return final_state

