def is_strobogrammatic_number(number: str) -> bool:
    """
    This function takes a string representation of a number and returns True if it is strobogrammatic, otherwise False.
    """
    # Define the mappings of strobogrammatic digits
    strobogrammatic_pairs = {'0': '0', '1': '1', '6': '9', '8': '8', '9': '6'}

    left, right = 0, len(number) - 1

    while left <= right:
        if number[left] not in strobogrammatic_pairs or strobogrammatic_pairs[number[left]] != number[right]:
            return False
        left += 1
        right -= 1

    return True

