def maxSublistSum(arr):
    """
    Returns the maximum sum of any non-empty sublist of the given list of integers.
    """
    if not arr:
        return 0

    max_current = max_global = arr[0]
    for num in arr[1:]:
        max_current = max(num, max_current + num)
        if max_current > max_global:
            max_global = max_current
    return max_global

