def get_diagonal_elements(matrix_dict):
    """
    Returns a dictionary of the diagonal elements of a square matrix.
    The input is a dictionary with keys as 'row,col' and values as matrix elements.
    """
    diagonal_elements = {}

    for key in matrix_dict:
        row, col = map(int, key.split(','))
        if row == col:
            diagonal_elements[key] = matrix_dict[key]

    return diagonal_elements

