def largest_substring(s, length):
    """
    Returns the lexicographically largest substring of given length.
    """
    # Validate input
    if s is None or length < 1 or length > len(s):
        return ""

    max_substring = ""
    for i in range(len(s) - length + 1):
        substring = s[i:i + length]
        if substring > max_substring:
            max_substring = substring

    return max_substring

