def PrimeFactorization(M):
    """
    Returns a dictionary where the keys are the prime factors of M and the values are their corresponding powers.
    """
    prime_factors = {}

    # Handle the smallest prime number, 2
    count = 0
    while M % 2 == 0:
        M //= 2
        count += 1
    if count > 0:
        prime_factors[2] = count

    # Handle odd prime numbers
    factor = 3
    while factor * factor <= M:
        count = 0
        while M % factor == 0:
            M //= factor
            count += 1
        if count > 0:
            prime_factors[factor] = count
        factor += 2

    # If M is still greater than 1, then it is prime
    if M > 1:
        prime_factors[M] = 1

    return prime_factors

