def search(nums, target):
    """
    Returns True if target exists in the rotated sorted array nums, otherwise False.
    """
    if not nums:
        return False

    left, right = 0, len(nums) - 1

    while left <= right:
        mid = (left + right) // 2

        if nums[mid] == target:
            return True

        # If we can't distinct the elements at left, mid and right
        if nums[left] == nums[mid] == nums[right]:
            left += 1
            right -= 1
        # When middle element is in the left part of rotated array
        elif nums[left] <= nums[mid]:
            # Check if target is in the left part
            if nums[left] <= target < nums[mid]:
                right = mid - 1
            else:
                left = mid + 1
        # When middle element is in the right part of rotated array
        else:
            # Check if target is in the right part
            if nums[mid] < target <= nums[right]:
                left = mid + 1
            else:
                right = mid - 1

    return False

