import math

def is_prime(n):
    """
    Returns True if n is a prime number, otherwise False.

    :param n: int, the number to check if it is a prime
    :return: bool, True if n is prime, False otherwise
    """
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def find_kth_missing_positive(arr, k):
    """
    Returns the k-th smallest missing positive integer from the array `arr`.
    """
    missing_count, current = 0, 1
    arr_set = set(arr)

    while missing_count < k:
        if current not in arr_set:
            missing_count += 1
        if missing_count < k:
            current += 1

    return current

