def longest_mountain(arr):
    if len(arr) < 3:
        return 0

    longest = 0
    n = len(arr)

    for i in range(1, n - 1):
        if arr[i-1] < arr[i] > arr[i+1]:
            left = i - 1
            right = i + 1

            while left > 0 and arr[left-1] < arr[left]:
                left -= 1
            while right < n - 1 and arr[right+1] < arr[right]:
                right += 1

            longest = max(longest, right - left + 1)

    return longest

def replace_f_with_t(dataset, columns):
    """
    Replaces all occurrences of "F" with "T" in the specified columns of the dataset.

    :param dataset: List of dictionaries, each dictionary represents a row in the dataset.
    :param columns: List of column names to check and replace "F" with "T".
    :return: Modified dataset with "F" replaced by "T" in the specified columns.
    """
    for row in dataset:
        for col in columns:
            if col in row and row[col] == "F":
                row[col] = "T"
    return dataset

