def unique_paths_with_obstacles(obstacle_grid):
    """
    Calculate the total number of distinct paths from the top-left corner to 
    the bottom-right corner of a grid with obstacles.

    :param obstacle_grid: List[List[int]] A 2D grid where 0 represents an empty cell 
                          and 1 represents an obstacle.
    :return: int The number of unique paths from the top-left corner to the 
                 bottom-right corner.
    """
    if not obstacle_grid or obstacle_grid[0][0] == 1:
        return 0

    m, n = len(obstacle_grid), len(obstacle_grid[0])
    dp = [[0] * n for _ in range(m)]
    dp[0][0] = 1

    for i in range(m):
        for j in range(n):
            if obstacle_grid[i][j] == 1:
                dp[i][j] = 0
            else:
                if i > 0:
                    dp[i][j] += dp[i-1][j]
                if j > 0:
                    dp[i][j] += dp[i][j-1]

    return dp[m-1][n-1]

def roman_to_int(s):
    """
    Convert Roman numeral string to integer. Handles cases with leading "X" repeated multiple times.
    """
    roman_values = {
        'I': 1, 'V': 5, 'X': 10, 'L': 50, 
        'C': 100, 'D': 500, 'M': 1000
    }

    total = 0
    prev_value = 0
    for char in reversed(s):
        value = roman_values[char]

        if value >= prev_value:
            total += value
        else:
            total -= value

        prev_value = value

    return total

