def is_valid_expression(s):
    """
    Determines if the input string s consists of a valid sequence of nested expressions.
    """
    stack = []
    matching_bracket = {')': '(', '}': '{', ']': '['}

    for char in s:
        if char in '({[':
            stack.append(char)
        elif char in ')}]':
            if not stack or stack[-1] != matching_bracket[char]:
                return False
            stack.pop()
    return not stack

