def categorize_numbers(numbers):
    """
    Categorizes numbers from the input list into 'low', 'medium', and 'high' based on predefined ranges.

    Args:
    numbers (list of int): List of integers to categorize.

    Returns:
    dict: Dictionary with keys 'low', 'medium', and 'high' and corresponding lists of integers.
    """

    categorized = {
        "low": [],
        "medium": [],
        "high": []
    }

    for number in numbers:
        if 1 <= number <= 33:
            categorized["low"].append(number)
        elif 34 <= number <= 66:
            categorized["medium"].append(number)
        elif 67 <= number <= 100:
            categorized["high"].append(number)

    return categorized

