def max_consecutive_sum(lst, k):
    if len(lst) < k:
        return 0

    max_sum = current_sum = sum(lst[:k])

    for i in range(k, len(lst)):
        current_sum += lst[i] - lst[i - k]
        max_sum = max(max_sum, current_sum)

    return max_sum

