def first_non_repeating(nums):
    """
    Returns the first non-repeating element in the array.
    If no such element exists, returns -1.
    """
    frequency = {}

    # First pass to count the frequency of each element
    for num in nums:
        if num in frequency:
            frequency[num] += 1
        else:
            frequency[num] = 1

    # Second pass to find the first non-repeating element
    for num in nums:
        if frequency[num] == 1:
            return num

    return -1

