from typing import List

def find_vowels(ascii_list: List[str]) -> List[str]:
    vowels = {'a', 'e', 'i', 'o', 'u'}
    result = []

    for digit_str in ascii_list:
        ascii_char = chr(int(digit_str))
        if ascii_char in vowels:
            result.append(ascii_char)
        else:
            result.append("not vowel")

    return result

import os

def manipulate_env(action, key, value=None):
    """
    Manipulates environment variables based on the given action.

    Parameters:
    action (str): The action to perform. Valid actions are "add", "modify", "delete", and "get".
    key (str): The key of the environment variable.
    value (str, optional): The value of the environment variable for "add" and "modify" actions.

    Returns:
    None for "add", "modify", and "delete" actions.
    The value of the environment variable for "get" action or `None` if it does not exist.
    """
    if action in ["add", "modify"]:
        os.environ[key] = value
    elif action == "delete":
        if key in os.environ:
            del os.environ[key]
    elif action == "get":
        return os.environ.get(key, None)
    return None

