def shortest_subsequence_with_k_distinct(sequence: str, k: int) -> int:
    if len(set(sequence)) < k:
        return -1

    n = len(sequence)
    min_length = n + 1

    for i in range(n):
        char_set = set()
        for j in range(i, n):
            char_set.add(sequence[j])
            if len(char_set) == k:
                min_length = min(min_length, j - i + 1)
                break

    return min_length if min_length != n + 1 else -1

