def get_histogram(input_list: list) -> dict:
    """
    Creates a histogram from the given list of integers, returning a dictionary
    with keys as the unique elements and values as their respective counts.
    """
    histogram = {}
    for num in input_list:
        if num in histogram:
            histogram[num] += 1
        else:
            histogram[num] = 1
    return histogram

