def word_pattern(pattern: str, string: str) -> bool:
    words = string.split()
    if len(pattern) != len(words):
        return False

    pattern_to_word = {}
    word_to_pattern = {}

    for p, w in zip(pattern, words):
        if p in pattern_to_word:
            if pattern_to_word[p] != w:
                return False
        else:
            if w in word_to_pattern:
                if word_to_pattern[w] != p:
                    return False
            pattern_to_word[p] = w
            word_to_pattern[w] = p

    return True

