import json
from typing import Dict, Tuple

def summarize_books(file_path: str) -> Dict[str, Tuple[int, float]]:
    """
    Summarizes books by genre, calculating the number of books and the average year of publication.
    """
    with open(file_path, 'r') as file:
        books = json.load(file)

    genre_summary = {}

    for book in books:
        genre = book["genre"]
        year = book["year"]

        if genre not in genre_summary:
            genre_summary[genre] = {"count": 0, "total_year": 0}

        genre_summary[genre]["count"] += 1
        genre_summary[genre]["total_year"] += year

    summary = {genre: (details["count"], details["total_year"] / details["count"]) 
               for genre, details in genre_summary.items()}

    return summary

