from collections import deque

def walls_and_gates(rooms):
    """
    Fills each empty room with the distance to its nearest gate. 
    If it is impossible to reach a gate, it remains filled with inf.
    """
    if not rooms or not rooms[0]:
        return

    m, n = len(rooms), len(rooms[0])
    queue = deque()

    # Initialize the queue with all the gates' positions
    for i in range(m):
        for j in range(n):
            if rooms[i][j] == 0:
                queue.append((i, j))

    # Perform BFS from the gates
    while queue:
        x, y = queue.popleft()
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            new_x, new_y = x + dx, y + dy
            if 0 <= new_x < m and 0 <= new_y < n and rooms[new_x][new_y] == 2147483647:
                rooms[new_x][new_y] = rooms[x][y] + 1
                queue.append((new_x, new_y))

def longest_chain(edits, references):
    from collections import defaultdict, deque

    # Create a dictionary to store the references of each edit
    references_dict = defaultdict(list)
    indegree = {edit: 0 for edit in edits}

    # Populate the dictionary and track indegree for topological sorting
    for edit1, edit2 in references:
        references_dict[edit2].append(edit1)
        indegree[edit1] += 1

    # We perform a topological sort using Kahn's algorithm
    queue = deque([edit for edit in edits if indegree[edit] == 0])
    longest_path = {edit: 1 for edit in edits}

    while queue:
        current = queue.popleft()
        for neighbor in references_dict[current]:
            indegree[neighbor] -= 1
            longest_path[neighbor] = max(longest_path[neighbor], longest_path[current] + 1)
            if indegree[neighbor] == 0:
                queue.append(neighbor)

    return max(longest_path.values())

