def frequency_dict(strings):
    """
    Takes a list of strings and returns a dictionary where each key is a unique string
    from the list and the value is the count of how many times that string appears in the list.
    """
    freq_dict = {}
    for string in strings:
        if string in freq_dict:
            freq_dict[string] += 1
        else:
            freq_dict[string] = 1
    return freq_dict

