def magic_sequence(n, k):
    if n == 1:
        return 1
    elif n == 2:
        return 2

    sequence = [1, 2]
    for i in range(2, n):
        next_value = sum(sequence[-k:])
        sequence.append(next_value)

    return sequence[n-1]

