def has_triplet_with_sum_zero(arr):
    """
    Checks if there exists a triplet in the array such that the sum of the triplet is zero.

    Args:
    arr (list of int): List of integers to check.

    Returns:
    bool: True if such a triplet exists, False otherwise.
    """
    arr.sort()
    n = len(arr)

    for i in range(n - 2):
        if i > 0 and arr[i] == arr[i - 1]:
            continue
        left, right = i + 1, n - 1
        while left < right:
            total = arr[i] + arr[left] + arr[right]
            if total == 0:
                return True
            elif total < 0:
                left += 1
            else:
                right -= 1

    return False

