from typing import List

def count_unique_triplets(nums: List[int], target: int) -> int:
    """
    Returns the number of unique triplets (a, b, c) in the array such that
    a + b + c = target and a <= b <= c.
    """
    nums.sort()
    triplet_set = set()
    n = len(nums)

    for i in range(n - 2):
        j = i + 1
        k = n - 1
        while j < k:
            total = nums[i] + nums[j] + nums[k]
            if total == target:
                triplet_set.add((nums[i], nums[j], nums[k]))
                j += 1
                k -= 1
            elif total < target:
                j += 1
            else:
                k -= 1

    return len(triplet_set)

