def longest_common_substring(str1, str2):
    """
    Returns the longest common substring between str1 and str2.
    If there are multiple substrings of the same length, returns any one of them.
    """
    len1, len2 = len(str1), len(str2)
    max_len = 0
    ending_index = 0
    dp = [[0] * (len2 + 1) for _ in range(len1 + 1)]

    for i in range(1, len1 + 1):
        for j in range(1, len2 + 1):
            if str1[i - 1] == str2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
                if dp[i][j] > max_len:
                    max_len = dp[i][j]
                    ending_index = i

    if max_len == 0:
        return ""

    return str1[ending_index - max_len: ending_index]

def is_prime(n):
    """
    Checks if a given number n is a prime number.
    Returns True if n is prime, otherwise returns False.
    """
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    max_divisor = int(n ** 0.5) + 1
    for divisor in range(3, max_divisor, 2):
        if n % divisor == 0:
            return False
    return True

