def count_vowels_consonants(s):
    """
    Returns a dictionary with the count of vowels and consonants in the input string.

    Args:
    s (str): Input string.

    Returns:
    dict: A dictionary with keys 'vowels' and 'consonants' and their respective counts.
    """
    vowels_set = set('aeiouAEIOU')
    vowels_count = 0
    consonants_count = 0

    for char in s:
        if char.isalpha():
            if char in vowels_set:
                vowels_count += 1
            else:
                consonants_count += 1

    return {'vowels': vowels_count, 'consonants': consonants_count}

