    """
    Returns the second smallest element in the array.
    If the second smallest element does not exist, return -1.
    """
    if N < 2:
        return -1

    first_smallest = float('inf')
    second_smallest = float('inf')

    for num in arr:
        if num < first_smallest:
            second_smallest = first_smallest
            first_smallest = num
        elif first_smallest < num < second_smallest:
            second_smallest = num

    return second_smallest if second_smallest != float('inf') else -1

