def max_profit(prices):
    """
    Calculate the maximum possible profit by buying and then later selling one share of stock.

    :param prices: List of daily stock prices.
    :return: Maximum possible profit, or 0 if no profit can be made.
    """
    if not prices:
        return 0

    min_price = float('inf')
    max_profit = 0

    for price in prices:
        if price < min_price:
            min_price = price
        elif price - min_price > max_profit:
            max_profit = price - min_price

    return max_profit

