def first_missing_positive(nums):
    """
    Returns the first missing positive number in the given list of integers.
    """
    n = len(nums)

    # Mark numbers (num < 0) and (num > n) with a special marker number (n+1)
    for i in range(n):
        if nums[i] <= 0 or nums[i] > n:
            nums[i] = n + 1

    # Use index as a hash key and number sign as a presence detector
    for i in range(n):
        num = abs(nums[i])
        if num <= n:
            nums[num - 1] = -abs(nums[num - 1])

    # The first index of a positive number is the missing smallest positive number
    for i in range(n):
        if nums[i] > 0:
            return i + 1

    return n + 1

