def index_of_largest_number(nums):
    """
    Returns the index of the first occurrence of the largest number in nums.
    If the list is empty, returns -1.
    """
    if not nums:
        return -1
    largest_num_index = 0
    for i in range(1, len(nums)):
        if nums[i] > nums[largest_num_index]:
            largest_num_index = i
    return largest_num_index

