def max_count_after_operations(m: int, n: int, ops: list) -> int:
    if not ops:
        return m * n

    min_r = m
    min_c = n

    for op in ops:
        min_r = min(min_r, op[0])
        min_c = min(min_c, op[1])

    return min_r * min_c

