def max_same_value_subarray_sum(arr):
    """
    Returns the maximum sum of any non-empty subarray such that all elements in the subarray have the same value.
    """
    if not arr:
        return 0

    max_sum = current_sum = arr[0]
    current_value = arr[0]

    for num in arr[1:]:
        if num == current_value:
            current_sum += num
        else:
            current_value = num
            current_sum = num
        max_sum = max(max_sum, current_sum)

    return max_sum

