def is_prime(number):
    """
    Determines if a number is prime.

    Args:
      number: The number to check.

    Returns:
      True if the number is prime, False otherwise.
    """
    if number <= 1:
        return False
    if number == 2 or number == 3:
        return True
    if number % 2 == 0 or number % 3 == 0:
        return False
    i = 5
    while i * i <= number:
        if number % i == 0 or number % (i + 2) == 0:
            return False
        i += 6
    return True

