def consolidate_orders(orders):
    """
    Consolidates the quantities for each unique product type from a list of orders.

    Parameters:
    orders (list of tuples): Each tuple contains a product name (str) and a quantity (int).

    Returns:
    dict: A dictionary where keys are product names and values are total quantities.
    """
    consolidated_inventory = {}

    for product, quantity in orders:
        if product in consolidated_inventory:
            consolidated_inventory[product] += quantity
        else:
            consolidated_inventory[product] = quantity

    return consolidated_inventory

