def min_operations_to_sort(nums):
    """
    Returns the minimum number of adjacent swaps required to sort the array in non-decreasing order.
    """
    swaps = 0
    n = len(nums)

    for i in range(n):
        for j in range(0, n-i-1):
            if nums[j] > nums[j+1]:
                nums[j], nums[j+1] = nums[j+1], nums[j]
                swaps += 1

    return swaps

