def word_frequency(s):
    """
    Converts a string containing words separated by spaces into a dictionary 
    where each key is a word and its value is the number of times it appears in the string.

    :param s: Input string
    :return: Dictionary with word frequency
    """
    words = s.split()
    frequency = {}

    for word in words:
        if word in frequency:
            frequency[word] += 1
        else:
            frequency[word] = 1

    return frequency

