def filter_list_by_frequency(lst, max_freq):
    count_map = {}
    result = []

    for num in lst:
        if num not in count_map:
            count_map[num] = 0
        if count_map[num] < max_freq:
            result.append(num)
            count_map[num] += 1

    return result

def is_prime(n):
    """
    Checks if the given number n is a prime number.
    A prime number is a natural number greater than 1 that has no positive divisors other than 1 and itself.
    """
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return False
    return True

