def unique_numbers(nums):
    """
    Returns a list of numbers that occur only once in the input list nums.

    Arguments:
    nums : list : input list of integers

    Returns:
    list : a list of integers that occur only once in nums
    """
    count_dict = {}
    for num in nums:
        if num in count_dict:
            count_dict[num] += 1
        else:
            count_dict[num] = 1

    result = []
    for num in nums:
        if count_dict[num] == 1:
            result.append(num)

    return result

