reference_solution:
def sieve_of_eratosthenes(n):
    """
    Finds all prime numbers between 1 and n using the Sieve of Eratosthenes algorithm.

    :param n: The upper limit of the range to find prime numbers
    :return: A list of prime numbers between 1 and n
    """
    if n < 2:
        return []

    is_prime = [True] * (n + 1)
    p = 2
    while (p * p <= n):
        if is_prime[p]:
            for i in range(p * p, n + 1, p):
                is_prime[i] = False
        p += 1

    return [p for p in range(2, n + 1) if is_prime[p]]

def find_unique_pairs(arr, target):
    """
    Returns a list of unique pairs of elements in the sorted array `arr` 
    such that their sum is equal to `target`.
    """
    pairs = []
    left, right = 0, len(arr) - 1

    while left < right:
        current_sum = arr[left] + arr[right]

        if current_sum == target:
            pairs.append((arr[left], arr[right]))
            left += 1
            right -= 1

            # Skip duplicates
            while left < right and arr[left] == arr[left - 1]:
                left += 1
            while left < right and arr[right] == arr[right + 1]:
                right -= 1

        elif current_sum < target:
            left += 1
        else:
            right -= 1

    return pairs

