reference_solution:
def longest_zigzag(arr):
    if len(arr) == 1:
        return 1

    increase = decrease = 1

    for i in range(1, len(arr)):
        if arr[i] > arr[i - 1]:
            increase = decrease + 1
        elif arr[i] < arr[i - 1]:
            decrease = increase + 1

    return max(increase, decrease)

