reference_solution:
def text_editor(n, operations):
    string = []
    history = []

    for op in operations:
        if op.startswith("ADD"):
            _, char = op.split()
            string.append(char)
            history.append(("ADD", char))
        elif op == "UNDO":
            if history:
                last_op, char = history.pop()
                if last_op == "ADD":
                    string.pop()

    return "".join(string)

