def interpret_code(file_path: str) -> list:
    """
    Interpret the code from the given file, evaluating expressions with eval()
    and statements with exec(). Collect and return results of evaluated
    expressions.
    """
    results = []
    with open(file_path, 'r') as file:
        code_lines = file.readlines()

    # Define a local execution and evaluation context
    local_vars = {}

    for line in code_lines:
        line = line.strip()
        if not line:
            continue

        try:
            # Try to evaluate the line as an expression
            result = eval(line, {}, local_vars)
            results.append(result)
        except:
            # If eval fails, treat the line as a statement
            try:
                exec(line, {}, local_vars)
            except Exception as e:
                print(f"Error executing line '{line}': {e}")

    return results

