def find_next_fibonacci(n):
    """
    Returns the smallest Fibonacci number greater than a given number n.
    """
    if n < 0:
        raise ValueError("Input should be a non-negative integer.")

    a, b = 0, 1
    while b <= n:
        a, b = b, a + b
    return b

