def smallest_prime_factor(n):
    """
    Returns the smallest prime factor of a given number n.
    If n is prime or 1, returns n itself.
    """
    if n <= 1:
        return n
    if n % 2 == 0:
        return 2
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return i
    return n

