def longest_alternating_subsequence(nums):
    n = len(nums)
    if n == 0:
        return 0

    up = [1] * n
    down = [1] * n

    for i in range(1, n):
        for j in range(i):
            if nums[i] > nums[j]:
                up[i] = max(up[i], down[j] + 1)
