reference_solution:
def countPaths(n, traps):
    if (0, 0) in traps or (n-1, n-1) in traps:
        return 0

    grid = [[0] * n for _ in range(n)]
    for trap in traps:
        grid[trap[0]][trap[1]] = -1

    grid[0][0] = 1

    for i in range(n):
        for j in range(n):
            if grid[i][j] == -1:
                continue

            if i > 0 and grid[i-1][j] != -1:
                grid[i][j] += grid[i-1][j]

            if j > 0 and grid[i][j-1] != -1:
                grid[i][j] += grid[i][j-1]

    return grid[n-1][n-1]

