from typing import List

def maxRob(nums: List[int]) -> int:
    if not nums:
        return 0
    if len(nums) <= 2:
        return max(nums)

    rob1, rob2 = 0, 0

    for num in nums:
        new_rob = max(rob2, rob1 + num)
        rob1 = rob2
        rob2 = new_rob

    return rob2

