def categorize_runner_finish_time(finish_time):
    """
    Returns the category of the runner based on their finish time in minutes.

    :param finish_time: int. The finish time in minutes.
    :return: str. The category of the runner.
    """
    if finish_time < 180:
        return "Elite Runner"
    elif 180 <= finish_time < 240:
        return "Competitive Runner"
    elif 240 <= finish_time < 300:
        return "Average Runner"
    else:
        return "Casual Runner"

