def transformString(s):
    """
    Transforms the string such that each character is followed by its frequency.
    """
    from collections import Counter

    frequency = Counter(s)
    result = []

    for char in s:
        if char not in result:
            result.append(char)
            result.append(str(frequency[char]))

    return ''.join(result)

