def length_of_longest_subarray(arr):
    """
    Returns the length of the longest contiguous subarray with unique elements.
    """
    if not arr:
        return 0

    max_length = 0
    current_start = 0
    seen = {}

    for current_end, value in enumerate(arr):
        if value in seen and seen[value] >= current_start:
            current_start = seen[value] + 1

        seen[value] = current_end
        max_length = max(max_length, current_end - current_start + 1)

    return max_length

