    return random.randint(1, 10)

def isValidParentheses(s):
    """
    Checks whether the input string s is a valid combination of parentheses.
    """
    stack = []
    mapping = {')': '(', '}': '{', ']': '['}

    for char in s:
        if char in mapping:
            top_element = stack.pop() if stack else '#'
            if mapping[char] != top_element:
                return False
        else:
            stack.append(char)

    return not stack

