def min_insertions_to_form_palindrome(s):
    """
    Returns the minimum number of insertions to form a palindrome.
    """
    n = len(s)
    dp = [[0] * n for _ in range(n)]

    for length in range(2, n+1):
        for i in range(n-length+1):
            j = i+length-1
            if s[i] == s[j]:
                dp[i][j] = dp[i+1][j-1]
            else:
                dp[i][j] = min(dp[i+1][j], dp[i][j-1]) + 1

    return dp[0][n-1]

