def unique_paths(m, n):
    """
    Returns the number of unique paths in an m x n grid moving only right or down.
    """
    if m == 1 or n == 1:
        return 1

    # Initialize a 2D array with 1s since there's only one path to each cell in the first row and first column
    dp = [[1]*n for _ in range(m)]

    for i in range(1, m):
        for j in range(1, n):
            dp[i][j] = dp[i-1][j] + dp[i][j-1]

    return dp[m-1][n-1]

def longest_substring_k_distinct(s: str, k: int) -> int:
    from collections import defaultdict

    if k == 0 or not s:
        return 0

    char_count = defaultdict(int)
    max_length = 0
    left = 0

    for right in range(len(s)):
        char_count[s[right]] += 1

        while len(char_count) > k:
            char_count[s[left]] -= 1
            if char_count[s[left]] == 0:
                del char_count[s[left]]
            left += 1

        max_length = max(max_length, right - left + 1)

    return max_length

