from sympy import diff, Symbol
from sympy.core.function import AppliedUndef

def differentiate(f, x):
    """
    Returns the derivative(s) of function(s) f with respect to variable x.
    If f is an array of functions, returns an array of derivatives.
    """
    if isinstance(f, list):
        return [diff(func, x) for func in f]
    else:
        return diff(f, x)

def is_valid_isbn10(isbn):
    """
    Returns True if the given ISBN-10 number is valid, False otherwise.

    An ISBN-10 number is valid if:
    1. It contains exactly 10 characters.
    2. It contains only digits 0-9 or 'X' (which represents the digit 10) as the last character.
    3. The sum of the digits multiplied by their position modulo 11 is zero.
    """
    if len(isbn) != 10:
        return False

    total = 0
    for i in range(9):
        if not isbn[i].isdigit():
            return False
        total += int(isbn[i]) * (i + 1)

    if isbn[9] == 'X':
        total += 10 * 10
    elif isbn[9].isdigit():
        total += int(isbn[9]) * 10
    else:
        return False

    return total % 11 == 0

