def count_words(word_list):
    """
    Takes a list of words and returns a dictionary with words as the keys 
    and their counts as the values. Words are counted in a case-insensitive manner.

    :param word_list: List of words
    :return: Dictionary with word counts
    """
    word_count = {}
    for word in word_list:
        word_lower = word.lower()
        if word_lower in word_count:
            word_count[word_lower] += 1
        else:
            word_count[word_lower] = 1
