def removeKChars(s, k):
    """
    Removes k characters from the string s such that the resulting string 
    is the largest lexicographically possible.
    """
    stack = []
    for char in s:
        while k > 0 and stack and stack[-1] < char:
            stack.pop()
            k -= 1
        stack.append(char)

    # If k characters are not removed, remove from the end of the stack
    while k > 0:
        stack.pop()
        k -= 1

    return ''.join(stack)

