def summarize_ranges(array):
    """
    Processes a sorted list of integers and returns a summary of consecutive ranges.

    Parameters:
        array (List[int]): A list of sorted integers with no duplicates.

    Returns:
        List[str]: A list of strings representing ranges of consecutive integers.
    """
    if not array:
        return []

    result = []
    start = array[0]
    end = array[0]

    for num in array[1:]:
        if num == end + 1:
            end = num
        else:
            if start == end:
                result.append(f"{start}")
            else:
                result.append(f"{start}-{end}")
            start = num
            end = num

    if start == end:
        result.append(f"{start}")
    else:
        result.append(f"{start}-{end}")

    return result

