def maxPower(artifacts):
    if not artifacts:
        return 0

    n = len(artifacts)
    if n == 1:
        return artifacts[0]
    if n == 2:
        return max(artifacts[0], artifacts[1])

    dp = [0] * n
    dp[0] = artifacts[0]
    dp[1] = max(artifacts[0], artifacts[1])

    for i in range(2, n):
        dp[i] = max(dp[i-1], dp[i-2] + artifacts[i])

    return dp[-1]

# Example usage
