reference_solution:
def firstUniqChar(s):
    """
    Returns the index of the first non-repeating character in the string s. 
    If no such character exists, returns -1.
    """
    # Dictionary to store the count of characters
    counts = {}
    for char in s:
        counts[char] = counts.get(char, 0) + 1

    # Find the index of the first non-repeating character
    for i in range(len(s)):
        if counts[s[i]] == 1:
            return i

    return -1

