def calculate_discount(price, discount):
    """
    Calculate the discounted price given the original price and discount percentage.

    :param price: original price (must be non-negative)
    :param discount: discount percentage (must be between 0 and 100)
    :return: discounted price
    """
    if price < 0 or discount < 0 or discount > 100:
        raise ValueError("Invalid price or discount value")

    return price - (price * discount / 100)

