def vowels_minus_consonants(s):
    """
    Returns the number of vowels minus the number of consonants in the string.
    """
    vowels = 'aeiouAEIOU'
    num_vowels = 0
    num_consonants = 0

    for char in s:
        if char.isalpha():
            if char in vowels:
                num_vowels += 1
            else:
                num_consonants += 1

    return num_vowels - num_consonants

