import math

def is_prime(n):
    """
    Determine if n is a prime number.

    Parameters:
    n (int): The number to check for primality.

    Returns:
    bool: True if n is a prime number, False otherwise.
    """
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False

    sq_root = int(math.sqrt(n))
    for i in range(3, sq_root + 1, 2):
        if n % i == 0:
            return False
    return True

