def isValid(s: str) -> bool:
    """
    Function to check if the string s is a valid set of nested parentheses.

    Parameters:
    s (str): A string containing characters '(', ')', '{', '}', '[' and ']'.

    Returns:
    bool: Returns True if the string forms a valid set of nested parentheses, otherwise returns False.
    """
    stack = []
    # Mapping of closing to opening parentheses
    parentheses_map = {')': '(', '}': '{', ']': '['}

    for char in s:
        if char in parentheses_map:
            top_element = stack.pop() if stack else '#'
            if parentheses_map[char] != top_element:
                return False
        else:
            stack.append(char)

    return not stack

