reference_solution:
def max_product_of_two(elements):
    """
    Returns the maximum product of two distinct elements in an array of non-negative integers.
    """
    if len(elements) < 2:
        return 0  # Not enough elements to form a product

    first_max = second_max = float('-inf')

    for num in elements:
        if num > first_max:
            first_max, second_max = num, first_max
        elif num > second_max:
            second_max = num

    return first_max * second_max

