reference_solution:
def is_rotation(list1, list2):
    """
    Check if list2 is a rotation of list1.
    """
    if len(list1) != len(list2):
        return False

    concatenated_list1 = list1 + list1
    return ''.join(map(str, list2)) in ''.join(map(str, concatenated_list1))

