def most_frequent_char(input_str: str) -> str:
    """
    Identify the most frequent character in a given string.
    If there's a tie, return the earliest occurring character in the string.
    """
    char_frequency = {}
    max_freq = 0
    max_char = input_str[0] if input_str else ''

    for char in input_str:
        if char in char_frequency:
            char_frequency[char] += 1
        else:
            char_frequency[char] = 1

        if char_frequency[char] > max_freq:
            max_freq = char_frequency[char]
            max_char = char
        elif char_frequency[char] == max_freq:
            # retain the max_char as is if char occurs later in the input_str
            if input_str.index(max_char) > input_str.index(char):
                max_char = char

    return max_char

def length_of_longest_substring(s):
    """
    Given a string s, return the length of the longest substring without repeating characters.
    """
    char_index_map = {}
    longest = 0
    start = 0

    for i, char in enumerate(s):
        if char in char_index_map and char_index_map[char] >= start:
            start = char_index_map[char] + 1
        char_index_map[char] = i
        longest = max(longest, i - start + 1)

    return longest

