def count_mines(grid):
    """
    Given a 2D list representing the Minesweeper grid where -1 represents a mine
    and 0 represents an empty cell, this function generates a new 2D list where
    each empty cell is replaced by the number of mines in its neighboring cells.

    Args:
    grid (List[List[int]]): A 2D list representing the Minesweeper grid.

    Returns:
    List[List[int]]: A new 2D list where each empty cell is replaced by the count of mines in its neighboring cells.
    """
    if not grid or not all(len(row) == len(grid[0]) for row in grid):
        raise ValueError("Grid must not be empty and must be rectangular.")

    rows = len(grid)
    cols = len(grid[0])
    result = [[0] * cols for _ in range(rows)]

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == -1:
                result[r][c] = -1
            else:
                mines_count = 0
                for dr in range(-1, 2):
                    for dc in range(-1, 2):
                        rr, cc = r + dr, c + dc
                        if 0 <= rr < rows and 0 <= cc < cols and grid[rr][cc] == -1:
                            mines_count += 1
                result[r][c] = mines_count

    return result

