def is_match(s: str, p: str) -> bool:
    """
    Returns True if the string s matches the pattern p, otherwise False.
    """

    # Create a DP table with False default values.
    dp = [[False] * (len(p) + 1) for _ in range(len(s) + 1)]

    # Empty string matches with empty pattern.
    dp[0][0] = True

    # Empty string match with pattern p.
    for j in range(1, len(p) + 1):
        if p[j-1] == '*':
            dp[0][j] = dp[0][j-2]

    # Fill the table for remaining cases.
    for i in range(1, len(s) + 1):
        for j in range(1, len(p) + 1):
            if p[j-1] == s[i-1] or p[j-1] == '.':
                dp[i][j] = dp[i-1][j-1]
            elif p[j-1] == '*':
                dp[i][j] = dp[i][j-2] or (dp[i-1][j] if p[j-2] == s[i-1] or p[j-2] == '.' else False)
            else:
                dp[i][j] = False

    return dp[len(s)][len(p)]

