def remove_duplicates(s):
    """
    Removes duplicate characters from the input string `s` and returns the resultant string
    such that each character appears exactly once and in the order of their first appearance.
    """
    seen = set()
    result = []
    for char in s:
        if char not in seen:
            seen.add(char)
            result.append(char)
    return "".join(result)

def fibonacci(n):
    """
    Returns the Fibonacci number at the given position n.
    """
    if n <= 0:
        return 0
    elif n == 1:
        return 1

    a, b = 0, 1
    for _ in range(2, n + 1):
        a, b = b, a + b
    return b

