def operation_calculator(operations):
    """
    Evaluates the arithmetic expression provided in operations string.

    :param operations: a string representing a valid arithmetic expression
    :return: the result of the expression as an integer, or "Invalid operation" for division by zero
    """
    try:
        # Evaluate the expression using eval. We assume the input is valid and safe as described.
        result = eval(operations)

        # Check if the result is a finite number.
        if isinstance(result, (int, float)):
            return int(result)
    except ZeroDivisionError:
        return "Invalid operation"

