from typing import List, Tuple

def search_key_in_sorted_matrix(matrix: List[List[int]], key: int) -> Tuple[int, int]:
    """
    Search for the given key in a matrix sorted in non-decreasing order both row-wise and column-wise.
    Returns the tuple of indices of the key if found, otherwise returns (-1, -1).
    """
    if not matrix or not matrix[0]:
        return (-1, -1)

    rows = len(matrix)
    cols = len(matrix[0])

    row = 0
    col = cols - 1

    while row < rows and col >= 0:
        if matrix[row][col] == key:
            return (row, col)
        elif matrix[row][col] < key:
            row += 1
        else:
            col -= 1

    return (-1, -1)

