def factorial(n):
    """
    Recursively calculates the factorial of a non-negative integer n.

    Parameters:
    n (int): a non-negative integer

    Returns:
    int: factorial of n if n is non-negative
    str: error message if n is negative
    """
    if n < 0:
        return "Factorial of negative number is not defined"
    elif n == 0:
        return 1
    else:
        return n * factorial(n - 1)

