def findMaxLength(nums):
    """
    This function returns the length of the longest contiguous subarray with equal number of 0s and 1s.

    Params:
        nums: list[int] - the list of integers (0s and 1s).

    Returns:
        int - the length of the longest subarray with equal number of 0s and 1s.
    """
    count_map = {0: -1}
    count = 0
    max_length = 0

    for i, num in enumerate(nums):
        if num == 0:
            count -= 1
        else:
            count += 1

        if count in count_map:
            max_length = max(max_length, i - count_map[count])
        else:
            count_map[count] = i

    return max_length

