def sum_even_numbers(nums):
    """
    Recursively calculates the sum of all even numbers in a list.
    """
    if not nums:
        return 0
    elif nums[0] % 2 == 0:
        return nums[0] + sum_even_numbers(nums[1:])
    else:
        return sum_even_numbers(nums[1:])

