from typing import List

def count_packages(weights: List[int]) -> List[int]:
    light, medium, heavy = 0, 0, 0

    for weight in weights:
        if weight < 5:
            light += 1
        elif 5 <= weight <= 10:
            medium += 1
        else:
            heavy += 1

    return [light, medium, heavy]

