def min_lexicographical_subsequence(command):
    """
    Function that returns the minimum lexicographical subsequence containing unique characters.
    """
    last_occurrence = {char: i for i, char in enumerate(command)}
    stack = []
    included = set()

    for i, char in enumerate(command):
        if char in included:
            continue
        while stack and stack[-1] > char and i < last_occurrence[stack[-1]]:
            removed = stack.pop()
            included.remove(removed)
        stack.append(char)
        included.add(char)

    return ''.join(stack)

def first_missing_positive(nums):
    """
    Finds the first missing positive integer in an array of integers.
    """
    n = len(nums)

    for i in range(n):
        while 1 <= nums[i] <= n and nums[nums[i] - 1] != nums[i]:
            nums[nums[i] - 1], nums[i] = nums[i], nums[nums[i] - 1]

    for i in range(n):
        if nums[i] != i + 1:
            return i + 1

    return n + 1

