from typing import List, Tuple

def transitive_closure(n: int, edges: List[Tuple[int, int]]) -> List[List[bool]]:
    # Initialize a matrix with False values
    closure = [[False] * n for _ in range(n)]

    # Each vertex is reachable from itself
    for i in range(n):
        closure[i][i] = True

    # Mark the given edges in the closure matrix
    for u, v in edges:
        closure[u][v] = True

    # Apply the Floyd-Warshall algorithm to find the transitive closure
    for k in range(n):
        for i in range(n):
            for j in range(n):
                if closure[i][k] and closure[k][j]:
                    closure[i][j] = True

    return closure

from typing import List

def rotate(mat: List[List[int]]) -> None:
    """
    Rotates the matrix by 90 degrees clockwise in place.
    """
    n = len(mat)

    # Transpose the matrix
    for i in range(n):
        for j in range(i, n):
            mat[i][j], mat[j][i] = mat[j][i], mat[i][j]

    # Reverse each row
    for i in range(n):
        mat[i].reverse()

