def longestEvenSubstring(s):
    """
    Returns the length of the longest substring where every character appears an even number of times.
    """
    n = len(s)
    if n == 0:
        return 0

    # dictionary to store the first occurrence of each state
    first_occurrence = {0: -1}  
    state = 0
    max_length = 0

    for i in range(n):
        # Calculate bitmask: toggle bit for current character
        state ^= (1 << (ord(s[i]) - ord('a')))

        if state in first_occurrence:
            max_length = max(max_length, i - first_occurrence[state])
        else:
            first_occurrence[state] = i

    return max_length

