def two_sum(nums, target):
    """
    Takes an array of integers and a target integer. 
    Finds two distinct integers in the array that add up to the target and returns their indices as a tuple.

    Args:
    nums: List of integers
    target: Integer target sum

    Returns:
    Tuple of two integers representing the indices of the two numbers.
    """
    indices_dict = {}
    for index, num in enumerate(nums):
        difference = target - num
        if difference in indices_dict:
            return (indices_dict[difference], index)
        indices_dict[num] = index

def calculateTrappedWater(heights):
    if not heights:
        return 0

    n = len(heights)
    left_max = [0] * n
    right_max = [0] * n

    left_max[0] = heights[0]
    for i in range(1, n):
        left_max[i] = max(left_max[i-1], heights[i])

    right_max[n-1] = heights[n-1]
    for i in range(n-2, -1, -1):
        right_max[i] = max(right_max[i+1], heights[i])

    water_trapped = 0
    for i in range(n):
        water_trapped += min(left_max[i], right_max[i]) - heights[i]

    return water_trapped

