def longest_balanced_substring(s):
    """
    Returns the length of the longest balanced substring of parentheses.
    """
    max_length = 0
    stack = [-1]  # Stack to store indices, initialized with -1

    for i, char in enumerate(s):
        if char == '(':
            stack.append(i)  # Push the index onto the stack
        else:
            stack.pop()  # Pop the top element
            if stack:
                max_length = max(max_length, i - stack[-1])
            else:
                stack.append(i)  # If stack is empty, push current index

    return max_length

