def is_palindrome_permutation(s: str) -> bool:
    """
    Check if the given string is a permutation of a palindrome.
    """
    # Normalize the string to ignore spaces and case differences.
    s = ''.join(filter(str.isalpha, s)).lower()

    # Count the frequency of each character.
    char_count = {}
    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Check the number of characters with odd counts.
    odd_count = 0
    for count in char_count.values():
        if count % 2 != 0:
            odd_count += 1
        if odd_count > 1:
            return False

    return True

