def most_frequent_char(s):
    """
    Returns the most frequently occurring character in the string.
    In case of a tie, returns the character that appears first.
    """
    char_count = {}
    max_char = ''
    max_count = 0

    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

        if char_count[char] > max_count or (char_count[char] == max_count and s.index(char) < s.index(max_char)):
            max_char = char
            max_count = char_count[char]

    return max_char

