import csv

def calculate_total_sales(input_csv, output_csv):
    try:
        sales_data = {}

        # Read the input CSV file
        with open(input_csv, mode='r') as infile:
            reader = csv.DictReader(infile)

            # Process each row
            for row in reader:
                try:
                    category = row['Category']
                    quantity_sold = int(row['QuantitySold'])
                    price_per_unit = float(row['PricePerUnit'])
                    total_sale = quantity_sold * price_per_unit

                    if category in sales_data:
                        sales_data[category] += total_sale
                    else:
                        sales_data[category] = total_sale
                except (KeyError, ValueError):
                    continue  # Skip row if there are missing fields or incorrect data types

        # Write the results to the output CSV file
        with open(output_csv, mode='w', newline='') as outfile:
            fieldnames = ['Category', 'TotalSales']
            writer = csv.DictWriter(outfile, fieldnames=fieldnames)

            writer.writeheader()
            for category, total_sales in sales_data.items():
                writer.writerow({'Category': category, 'TotalSales': total_sales})
    except Exception as e:
        print(f"An error occurred: {e}")

