def sieve_of_eratosthenes(n):
    """
    Function to generate prime numbers up to a given number n.
    """
    if n < 2:
        return []

    primes = [True] * (n + 1)
    primes[0] = primes[1] = False

    for num in range(2, int(n**0.5) + 1):
        if primes[num]:
            for multiple in range(num * num, n + 1, num):
                primes[multiple] = False

    return [num for num, is_prime in enumerate(primes) if is_prime]

from collections import deque
from typing import List

def walls_and_gates(grid: List[List[int]]) -> None:
    if not grid or not grid[0]:
        return

    m, n = len(grid), len(grid[0])
    INF = 2147483647
    queue = deque()

    # Initialize the queue with all gates' positions
    for i in range(m):
        for j in range(n):
            if grid[i][j] == 0:
                queue.append((i, j))

    # Directions for moving up, down, left and right
    directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]

    # Perform BFS from all gates simultaneously
    while queue:
        x, y = queue.popleft()
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < m and 0 <= ny < n and grid[nx][ny] == INF:
                grid[nx][ny] = grid[x][y] + 1
                queue.append((nx, ny))

question:
Create a function that takes a list of integers and returns the length of the longest subsequence in which the numbers are in an increasing order.

For example:

```
longest_increasing_subsequence([10, 22, 9, 33, 21, 50, 41, 60]) => 5
// The longest increasing subsequence is [10, 22, 33, 50, 60]

longest_increasing_subsequence([3, 10, 2, 1, 20]) => 3
// The longest increasing subsequence is [3, 10, 20]

longest_increasing_subsequence([3, 2]) => 1
// The longest increasing subsequence is [3] or [2]

longest_increasing_subsequence([50, 3, 10, 7, 40, 80]) => 4
// The longest increasing subsequence is [3, 7, 40, 80]
```

reference_solution:
def longest_increasing_subsequence(sequence):
    if not sequence:
        return 0

    lengths = [1] * len(sequence)

    for i in range(1, len(sequence)):
        for j in range(i):
            if sequence[i] > sequence[j]:
                lengths[i] = max(lengths[i], lengths[j] + 1)

    return max(lengths)

