    Manage file descriptor locks using fcntl.

    Parameters:
    - file_path (str): The path to the file on which the lock operation will be performed.
    - command (str): The locking operation to be performed ('LOCK_SH_NON_BLOCK', 'LOCK_EX', 'LOCK_UN').

    Returns:
    - str: A success message indicating the performed operation or an error message if the operation failed.
    """
    try:
        with open(file_path, 'r+') as file:
            if command == "LOCK_SH_NON_BLOCK":
                try:
                    fcntl.lockf(file, fcntl.LOCK_SH | fcntl.LOCK_NB)
                    return "Shared lock acquired without blocking"
                except OSError as e:
                    return f"Failed to acquire shared lock without blocking: {e}"
            elif command == "LOCK_EX":
                fcntl.lockf(file, fcntl.LOCK_EX)
                return "Exclusive lock acquired"
            elif command == "LOCK_UN":
                fcntl.lockf(file, fcntl.LOCK_UN)
                return "Lock released"
            else:
                return "Invalid command"

    except OSError as e:
        return f"Error handling lock: {e}"

