def encode_string(s):
    """
    Encodes a string by replacing each letter with the letter three places ahead in the alphabet.
    Wraps around so that 'z' becomes 'c'. Spaces and punctuation remain unchanged.

    Args:
    s (string): Input string to encode

    Returns:
    string: Encoded string
    """
    result = []
    for char in s:
        if char.isalpha():
            # Get the ASCII code of the char and apply the shift
            if char.islower():
                encoded_char = chr((ord(char) - 97 + 3) % 26 + 97)
            else:
                encoded_char = chr((ord(char) - 65 + 3) % 26 + 65)
            result.append(encoded_char)
        else:
            result.append(char)
    return ''.join(result)

print(encode_string("hello world"))  # Expected to print: "khoor zruog"

def transform_string(s):
    """
    Transforms the input string by replacing each digit with its English word representation and each letter 
    by its position in the alphabet, then appends a hyphen '-' between every two characters in the resultant string.
    :param s: A string consisting of digits and lowercase letters.
    :return: Transformed string as per the problem statement.
    """
    digit_to_word = {
        '0': 'zero', '1': 'one', '2': 'two', '3': 'three', '4': 'four', 
        '5': 'five', '6': 'six', '7': 'seven', '8': 'eight', '9': 'nine'
    }

    result = []
    for char in s:
        if char.isdigit():
            result.append(digit_to_word[char])
        elif char.isalpha():
            result.append(str(ord(char) - ord('a') + 1))

    return '-'.join(result)

