def first_non_repeating_character(s):
    """
    Returns the first non-repeating character in the given string.
    If all characters are repeating, returns an underscore ('_').
    """
    # Dictionary to store the count of each character
    char_count = {}

    # Iterate over the string and populate the dictionary with character counts
    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Iterate over the string again to find the first non-repeating character
    for char in s:
        if char_count[char] == 1:
            return char

    # If no non-repeating character is found, return '_'
    return '_'

