import heapq

class Solution:
    def orangesRotting(self, grid: List[List[int]]) -> int:
        rows, cols = len(grid), len(grid[0])
        queue, fresh = [], []
        for r in range(rows):
            for c in range(cols):
                if grid[r][c] == 1:
                    fresh.append((r,c))
                elif grid[r][c] == 2:
                    heapq.heappush(queue, (0, r, c))
        minutes = 0
        while queue and fresh:
            mins, r, c  = heapq.heappop(queue)
            if (r, c) not in fresh:
                continue
            fresh.remove((r, c))
            minutes = max(minutes, mins)
            for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                x, y = r + dx, c + dy
                if x < 0 or x >= rows or y < 0 or y >= cols:
                    continue
                if grid[x][y] != 1:
                    continue
                heapq.heappush(queue, (mins + 1, x, y))
                fresh.remove((x, y))
        return minutes if not fresh else -1

