from typing import List, Tuple, Optional

def detect_one_sparse(stream: List[Tuple[int, str]]) -> Optional[int]:
    """
    Determine if the sequence is 1-sparse, and if so, return the unique number.
    If not, return None.
    """
    counter = {}

    for num, sign in stream:
        if sign == '+':
            if num in counter:
                counter[num] += 1
            else:
                counter[num] = 1
        elif sign == '-':
            if num in counter:
                counter[num] -= 1
            else:
                counter[num] = -1

    unique_nums = [num for num, count in counter.items() if count != 0]

    if len(unique_nums) == 1:
        return unique_nums[0]
    else:
        return None

