from typing import List

def min_bills(bills: List[int], target: int) -> int:
    # Initialize a list to store the minimum number of bills needed for each amount up to target
    dp = [float('inf')] * (target + 1)
    dp[0] = 0  # 0 bills are needed to make up the target amount of 0

    # Process each amount from 1 to target
    for amount in range(1, target + 1):
        for bill in bills:
            if amount - bill >= 0:
                dp[amount] = min(dp[amount], dp[amount - bill] + 1)

    return dp[target] if dp[target] != float('inf') else -1

def is_perfect_cube(n):
    """
    Returns True if n is a perfect cube, otherwise returns False.
    """
    if n < 0:
        cube_root = round(abs(n) ** (1/3)) * -1
    else:
        cube_root = round(n ** (1/3))
    return cube_root ** 3 == n

