def count_digits(s):
    """
    Counts the occurrence of each digit (from 0 to 9) in the given string s.

    Parameters:
    s (str): The input string containing digits and whitespace

    Returns:
    dict: A dictionary with digits as keys and their counts as values
    """
    digit_count = {str(digit): 0 for digit in range(10)}
    for char in s:
        if char.isdigit():
            digit_count[char] += 1
    return digit_count

