def count_distinct_vowels(s):
    """
    Returns the count of distinct vowels in the given string. The function is case-insensitive.

    Args:
    s (str): The input string.

    Returns:
    int: The count of distinct vowels.
    """
    vowels = {'a', 'e', 'i', 'o', 'u'}
    s = s.lower()
    distinct_vowels = set()

    for char in s:
        if char in vowels:
            distinct_vowels.add(char)

    return len(distinct_vowels)

