def two_sum(nums, target):
    """
    Given a list of integers, find two numbers in the list that add up to the target sum.
    Return the indices of the two numbers. If there are multiple pairs, return any one of them.
    If no such pair exists, return an empty list.
    """
    num_to_index = {}
    for i, num in enumerate(nums):
        complement = target - num
        if complement in num_to_index:
            return sorted([i, num_to_index[complement]])
        num_to_index[num] = i
    return []

def evaluate_expressions(expressions):
    """
    Evaluates a list of mathematical expressions.
    Returns a list of results or 'Error' for invalid expressions and division by zero.
    """
    results = []
    for expr in expressions:
        try:
            result = eval(expr)
            results.append(result)
        except ZeroDivisionError:
            results.append('Error')
        except (SyntaxError, NameError):
            results.append('Error')
    return results

from typing import List

def transpose_and_rotate(matrix: List[List[int]]) -> None:
    """
    This function takes a square matrix, first transposes it, and then rotates it 90 degrees clockwise.
    """
    n = len(matrix)

    # Transpose the matrix
    for i in range(n):
        for j in range(i+1, n):
            matrix[i][j], matrix[j][i] = matrix[j][i], matrix[i][j]

    # Rotate the matrix 90 degrees clockwise by reversing each row
    for i in range(n):
        matrix[i].reverse()

