def findWealthiestUser(transactions):
    """
    Finds the user with the highest net balance from a list of transactions.
    Each transaction is a tuple (sender_id, receiver_id, amount).
    """
    balances = {}

    for sender_id, receiver_id, amount in transactions:
        if sender_id not in balances:
            balances[sender_id] = 0
        if receiver_id not in balances:
            balances[receiver_id] = 0

        balances[sender_id] -= amount
        balances[receiver_id] += amount

    max_balance = float('-inf')
    wealthiest_user = None

    for user_id in balances:
        if balances[user_id] > max_balance or (balances[user_id] == max_balance and user_id < wealthiest_user):
            max_balance = balances[user_id]
            wealthiest_user = user_id

    return wealthiest_user

def knapsack(values, weights, max_weight):
    n = len(values)
    # Table to store results of subproblems
    dp = [[0] * (max_weight + 1) for _ in range(n + 1)]

    for i in range(1, n + 1):
        for w in range(max_weight + 1):
            if weights[i-1] <= w:
                dp[i][w] = max(values[i-1] + dp[i-1][w-weights[i-1]], dp[i-1][w])
            else:
                dp[i][w] = dp[i-1][w]

    return dp[n][max_weight]

