def finalPosition(movements: str):
    """
    Returns the final coordinates of the robot after performing all the movements.
    """
    x, y = 0, 0

    for move in movements:
        if move == 'U':
            y += 1
        elif move == 'D':
            y -= 1
        elif move == 'L':
            x -= 1
        elif move == 'R':
            x += 1

    return (x, y)
